+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
+                                                &larr; Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < _columns.Length - 1)
+                                        {
+                                            var rightStatus = _columns[colIndex + 1];
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
+                                                Move Right &rarr;
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (_showFormForColumn == colName)
+                        {
+                            <div class="card border-primary mt-auto">
+                                <div class="card-body p-2">
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Title" @bind="_newTitle" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm"
+                                               placeholder="Assignee" @bind="_newAssignee" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <select class="form-select form-select-sm" @bind="_newPriority">
+                                            <option value="High">High</option>
+                                            <option value="Medium">Medium</option>
+                                            <option value="Low">Low</option>
+                                        </select>
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="date" class="form-control form-control-sm"
+                                               @bind="_newDueDate" />
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm"
+                                                @onclick="() => SaveNewTaskAsync(colName)">
+                                            Save
+                                        </button>
+                                        <button class="btn btn-outline-secondary btn-sm"
+                                                @onclick="CancelAddTask">
+                                            Cancel
+                                        </button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-outline-primary btn-sm mt-auto"
+                                    @onclick="() => ShowAddForm(colName)">
+                                + Add Task
+                            </button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _errorMessage;
+    private string _searchText = string.Empty;
+
+    // Add-task form state
+    private string? _showFormForColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private IEnumerable<TaskItem> GetTasksForColumn(string status)
+        => _allTasks.Where(t => t.Status == status);
+
+    private IEnumerable<TaskItem> GetFilteredTasksForColumn(string status)
+        => GetTasksForColumn(status)
+            .Where(t => string.IsNullOrWhiteSpace(_searchText)
+                || t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
+
+    private static string GetPriorityBadgeClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = _allTasks.First(t => t.Id == taskId);
+            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+    }
+
+    private void ShowAddForm(string column)
+    {
+        _showFormForColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAddTask()
+    {
+        _showFormForColumn = null;
+    }
+
+    private async Task SaveNewTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+            _allTasks.Add(created);
+            _showFormForColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+    }
+}
+

